private fun extractActionFromIntent(intent: Intent?): String? {
    // The activity is exported (launcher entry point), so this extra is
    // attacker-controlled: any co-resident app can start MainActivity and
    // supply an arbitrary value. Only the actions this app actually
    // implements may be forwarded to the Dart layer.
    val actionExtra = intent?.getStringExtra("extra_flames_action")
    if (!actionExtra.isNullOrBlank()) {
        val action = actionExtra.trim()
        if (action !in ALLOWED_ACTIONS) {
            return null
        }
        pendingAction = action
        return action
    }
    if (intent?.action == FlamesQuickTile.ACTION_QUICK_TILE_TRIGGER) {
        val fallbackAction = "voice_input"
        pendingAction = fallbackAction
        return fallbackAction
    }
    return null
}

