/// Returns `null` when [url] is acceptable, else a short human message.
static String? validateUrl(String url) {
  final trimmed = url.trim();
  if (trimmed.isEmpty) return 'URL is empty';
  final uri = Uri.tryParse(trimmed);
  if (uri == null) return 'URL is missing a host';
  final scheme = uri.scheme.toLowerCase();
  if (scheme != 'http' && scheme != 'https') {
    return 'Unsupported URL scheme: ${uri.scheme}';
  }
  if (uri.host.isEmpty) return 'URL is missing a host';
  if (_isNonPublicHost(uri.host)) {
    return 'Refusing to fetch a loopback, private, link-local, or '
        'reserved address: ${uri.host}';
  }
  return null;
}

/// Whether [rawHost] names a loopback, private, link-local, or otherwise
/// non-public address that the reader must never fetch.
static bool _isNonPublicHost(String rawHost) {
  var host = rawHost.toLowerCase();
  while (host.endsWith('.')) {
    host = host.substring(0, host.length - 1);
  }
  if (host.isEmpty) return true;
  if (host == 'localhost' || host.endsWith('.localhost')) return true;
  if (host.endsWith('.local') ||
      host.endsWith('.internal') ||
      host.endsWith('.home.arpa')) {
    return true;
  }

  final octets = _ipv4Octets(host);
  if (octets != null) return _isNonPublicIpv4(octets);

  if (host.contains(':')) return _isNonPublicIpv6(host);

  // Decimal, hexadecimal, and octal spellings of an IPv4 address.
  if (RegExp(r'^(?:0[xX][0-9a-fA-F]+|[0-9]+)$').hasMatch(host)) return true;
  return false;
}

static List<int>? _ipv4Octets(String host) {
  final parts = host.split('.');
  if (parts.length != 4) return null;
  final octets = <int>[];
  for (final part in parts) {
    if (part.isEmpty || part.length > 3) return null;
    if (!RegExp(r'^[0-9]+$').hasMatch(part)) return null;
    final value = int.parse(part);
    if (value > 255) return null;
    octets.add(value);
  }
  return octets;
}

static bool _isNonPublicIpv4(List<int> octets) {
  final first = octets[0];
  final second = octets[1];
  if (first == 0 || first == 10 || first == 127) return true;
  if (first == 169 && second == 254) return true;
  if (first == 172 && second >= 16 && second <= 31) return true;
  if (first == 192 && second == 168) return true;
  if (first == 100 && second >= 64 && second <= 127) return true;
  if (first >= 224) return true;
  return false;
}

static bool _isNonPublicIpv6(String host) {
  if (host == '::' || host == '::1') return true;
  if (host.startsWith('fe8') ||
      host.startsWith('fe9') ||
      host.startsWith('fea') ||
      host.startsWith('feb')) {
    return true;
  }
  if (host.startsWith('fc') || host.startsWith('fd')) return true;
  if (host.startsWith('2002:') || host.startsWith('64:ff9b:')) return true;
  if (host.startsWith('::ffff:')) {
    final tail = host.substring('::ffff:'.length);
    final octets = _ipv4Octets(tail);
    if (octets != null) return _isNonPublicIpv4(octets);
    final groups = tail.split(':');
    if (groups.length == 2) {
      final high = int.tryParse(groups[0].padLeft(4, '0'), radix: 16);
      final low = int.tryParse(groups[1].padLeft(4, '0'), radix: 16);
      if (high != null && low != null) {
        return _isNonPublicIpv4([
          (high >> 8) & 0xff,
          high & 0xff,
          (low >> 8) & 0xff,
          low & 0xff,
        ]);
      }
    }
    return true;
  }
  return false;
}

