/// Maximum number of redirect hops [fetchUrl] will follow.
static const int _maxRedirects = 5;

/// Fetches [url] and returns the raw response body (HTML).
///
/// Redirects are followed manually so that every hop is re-validated by
/// [UrlReaderServiceBase.validateUrl]. The HTTP client itself never follows
/// a redirect, which would otherwise let a public URL bounce the request to
/// a loopback, private, or link-local address.
Future<Either<Failure, String>> fetchUrl(String url) async {
  var current = url;
  try {
    for (var hop = 0; hop <= _maxRedirects; hop++) {
      final validationError = UrlReaderServiceBase.validateUrl(current);
      if (validationError != null) {
        return Left(ValidationFailure(validationError));
      }

      final response = await _dio.get<String>(
        current,
        options: Options(
          responseType: ResponseType.plain,
          followRedirects: false,
          headers: const {
            'User-Agent': _userAgent,
            'Accept': _accept,
            'Accept-Language': _acceptLanguage,
          },
        ),
      );

      final status = response.statusCode ?? 0;
      if (status < 300 || status >= 400) {
        final body = response.data;
        if (body == null || body.trim().isEmpty) {
          return Left(ParseFailure('No readable content found at $url'));
        }
        return Right(body);
      }

      final location = response.headers.value('location');
      if (location == null || location.trim().isEmpty) {
        return Left(ParseFailure('No readable content found at $url'));
      }
      current = Uri.parse(current).resolve(location.trim()).toString();
    }
    return Left(NetworkFailure('Too many redirects while fetching $url'));
  } on DioException catch (e) {
    return Left(NetworkFailure(_describeDioError(e, url)));
  } catch (e) {
    return Left(
      NetworkFailure(
        FailureMessage.humanize(e, context: 'Failed to fetch the page'),
      ),
    );
  }
}

