/// Maps one plugin file to a payload. Returns null when the path is empty or,
/// for file-backed kinds, when the plugin-resolved path escapes its root.
///
/// The share-intent plugin copies provider-supplied `content://` streams into
/// `context.cacheDir` using a `_display_name` value it does not sanitise, so a
/// hostile provider can return a name carrying `..` segments. Such a path must
/// never be forwarded into an agent prompt.
SharedPayload? mapFile(SharedMediaFile file) {
  if (file.path.trim().isEmpty) return null;
  final kind = _mapKind(file.type);
  if (_isFileBacked(kind) && _hasParentTraversal(file.path)) return null;
  return SharedPayload(
    kind: kind,
    value: file.path,
    mimeType: file.mimeType,
    thumbnail: file.thumbnail,
    message: file.message,
  );
}

/// True when the payload names a file on disk rather than free text or a URL.
bool _isFileBacked(SharedPayloadKind kind) =>
    kind == SharedPayloadKind.image ||
    kind == SharedPayloadKind.video ||
    kind == SharedPayloadKind.file;

/// True when any path segment is `..`, i.e. the path can name a location
/// outside the directory the plugin intended to write into.
bool _hasParentTraversal(String path) => path.split('/').contains('..');

technical_analysis:
## The dispatcher has no state guard

`GatewayClient._handleIncomingData` is the single entry point for every inbound frame. While the connection is `connecting`, it intercepts exactly two message types and returns:

```dart title=lib/data/datasources/remote/gateway/gateway_client.dart startLineNumber=240 endLineNumber=259
      if (_state == GatewayConnectionState.connecting) {
        if (message is GatewayAuthSuccessMessage) {
          _authTimer?.cancel();
          _authTimer = null;
          _reconnectAttempts = 0;
          _setState(GatewayConnectionState.connected);
          _startHeartbeat();
          _sendToolManifest();
          _messageController.add(message);
          return;
        } else if (message is GatewayAuthFailureMessage) {
          _authTimer?.cancel();
          _authTimer = null;
          _manuallyDisconnected = true; // Never auto-reconnect on auth rejection
          _cleanUpSocket(_CloseCause.authRejected);
          _setState(GatewayConnectionState.disconnected);
          _messageController.add(message);
          return;
        }
      }
```

Every other frame type falls out of that block and reaches the dispatcher below. That dispatcher carries a comment claiming a state precondition it does not enforce:

```dart title=lib/data/datasources/remote/gateway/gateway_client.dart startLineNumber=261 endLineNumber=277
      // If connected:
      if (message is GatewayPingMessage) {
        send(GatewayPongMessage(timestamp: message.timestamp));
      } else if (message is GatewayPongMessage) {
        _watchdogTimer?.cancel();
        _watchdogTimer = null;
      } else if (message is GatewayTextDeltaMessage) {
        _textDeltaController.add(message);
      } else if (message is GatewayToolCallRequestMessage) {
        if (!_toolCallRequestController.hasListener) {
          sendToolCallResponse(
            callId: message.id,
            error: 'Device RPC receiver is not listening',
