/// Roles a gateway peer is permitted to claim. Everything else - notably
/// `system`, which the application reserves for locally-authored
/// instructions - is coerced to a data role so a remote frame can never
/// carry instruction authority.
static const Set<String> _allowedRoles = {'assistant', 'user'};

static String _sanitizeRole(Object? raw) {
  final normalized = (raw ?? 'user').toString().trim().toLowerCase();
  return _allowedRoles.contains(normalized) ? normalized : 'assistant';
}

factory GatewayChatMessage.fromJson(Map<String, dynamic> json) {
  return GatewayChatMessage(
    content: (json['content'] ?? json['message'] ?? '').toString(),
    role: _sanitizeRole(json['role']),
    metadata: json['metadata'] as Map<String, dynamic>?,
  );
}

