code_locations.fix_after:
import 'dart:async';
import 'dart:io';

/// An [HttpClient] whose requests never follow HTTP redirects.
///
/// The WebSocket handshake is an ordinary GET, and dart:io's default client
/// follows redirects on it. A redirect would move the handshake - and the
/// authentication frame written immediately afterwards - to an origin the
/// user never configured, disclosing the gateway bearer token. Disabling
/// redirects on the handshake pins the connection to the configured origin.
class _NoRedirectHttpClient implements HttpClient {
  final HttpClient _inner = HttpClient();

  @override
  Future<HttpClientRequest> openUrl(String method, Uri url) async {
    final request = await _inner.openUrl(method, url);
    request.followRedirects = false;
    return request;
  }

  @override
  dynamic noSuchMethod(Invocation invocation) => throw UnsupportedError(
        '_NoRedirectHttpClient does not implement ${invocation.memberName}',
      );
}

